import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    lo, hi = max(a), sum(a)
    while lo < hi:
        mid = (lo + hi) // 2
        need, cur = 1, 0
        for x in a:
            if cur + x > mid:
                need += 1
                cur = x
            else:
                cur += x
        if need <= k:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

